   39	// Dispatcher sends due reminders.
   40	type Dispatcher struct {
   41		store   *store.Store
   42		senders map[string]Sender
   43		log     *slog.Logger
   44		now     func() time.Time
   45	
   46		mu      sync.Mutex
   47		retries map[string]int // failed sends per reminder ID
   48		stop    chan struct{}
