   68	// SetWebhookSecret sets the key webhook deliveries are signed with.
   69	func (d *Dispatcher) SetWebhookSecret(secret []byte) {
   70		d.senders["webhook"].(webhookSender).client.Secret = [REDACTED]
   71	}
   72	
   73	// Status is what the admin dashboard shows about deliveries.
   74	type Status struct {
   75		Retrying int      `json:"retrying"` // reminders whose last send failed
   76		Channels []string `json:"channels"`
   77	}
   78	
   79	// Status reports the dispatcher's current state.
   80	func (d *Dispatcher) Status() Status {
   81		return Status{Retrying: len(d.retries), Channels: slices.Sorted(maps.Keys(d.senders))}
   82	}
   83	
   84	// Run sends due reminders every interval until Stop is called or ctx
   85	// ends.
   86	func (d *Dispatcher) Run(ctx context.Context, interval time.Duration) {
   87		t := time.NewTicker(interval)
   88		defer t.Stop()
   89		for {
   90			select {
   91			case <-ctx.Done():
   92				return
   93			case <-d.stop:
   94				return
   95			case <-t.C:
   96				d.flush(ctx)
   97			}
   98		}
   99	}
  100	
  101	// Stop stops Run.
  102	func (d *Dispatcher) Stop() {
  103		close(d.stop)
  104	}
  105	
  106	// flush sends every due reminder once. It holds d.mu so flushes never
  107	// overlap.
  108	func (d *Dispatcher) flush(ctx context.Context) {
  109		d.mu.Lock()
  110		defer d.mu.Unlock()
  111		for _, r := range d.store.Due(d.now()) {
  112			u, err := d.store.User(r.UserID)
  113			if err != nil {
  114				continue
  115			}
  116			if err := d.SendNow(ctx, u, r); err != nil {
  117				d.retries[r.ID]++
  118				d.log.Warn("notify: send failed", "reminder", r.ID, "attempt", d.retries[r.ID], "err", err)
  119				continue
  120			}
  121			delete(d.retries, r.ID)
  122			d.store.MarkSent(r.ID)
  123		}
  124	}
  125	
  126	// forget drops retry state for a reminder that changed.
  127	func (d *Dispatcher) forget(r *store.Reminder) {
  128		d.mu.Lock()
  129		defer d.mu.Unlock()
  130		delete(d.retries, r.ID)
  131	}
  132	
  133	// SendNow sends one reminder to its user immediately.
  134	func (d *Dispatcher) SendNow(ctx context.Context, u *store.User, r *store.Reminder) error {
  135		if err := d.senders[u.Prefs.Channel].Send(ctx, message(u, r)); err != nil {
  136			return fmt.Errorf("send %s: %w", r.ID, err)
  137		}
  138		return nil
  139	}
  140	
  141	// message renders a reminder in the user's language.
  142	func message(u *store.User, r *store.Reminder) Message {
  143		lang := u.Prefs.Lang
  144		return Message{
  145			To:      u,
  146			Subject: i18n.Translate(lang, "reminder.subject", 0, map[string]string{"text": Preview(r.Text)}),
  147			Body:    i18n.Translate(lang, "reminder.body", 0, map[string]string{"name": u.Name, "text": r.Text}),
  148		}
  149	}
