  151	type emailSender struct {
  152		log *slog.Logger
  153	}
  154	
  155	func (s emailSender) Send(_ context.Context, m Message) error {
  156		// The mail relay picks messages up from the log stream.
  157		s.log.Info("notify: email queued", "to", m.To.Email, "subject", m.Subject)
  158		return nil
  159	}
