  162		client *webhook.Client
  163		now    func() time.Time
  164	}
  165	
  166	func (s webhookSender) Send(ctx context.Context, m Message) error {
  167		body, err := json.Marshal(map[string]string{"subject": m.Subject, "body": m.Body})
  168		if err != nil {
  169			return fmt.Errorf("webhook: %w", err)
  170		}
  171		d := &webhook.Delivery{
  172			ID:      fmt.Sprintf("whd_%d", s.now().UnixNano()),
  173			URL:     m.To.Prefs.Webhook,
  174			Event:   "reminder.due",
  175			Payload: body,
  176			Created: s.now(),
  177		}
  178		if err := s.client.Post(ctx, d); err != nil {
  179			return fmt.Errorf("webhook to %s: %w", d.URL, err)
  180		}
